CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE kelurahan(id INTEGER PRIMARY KEY, nama TEXT, kecamatan TEXT, kota TEXT, provinsi TEXT, alamat TEXT, kode_pos TEXT, lurah TEXT, nip_lurah TEXT, telp TEXT);
CREATE TABLE rw(id INTEGER PRIMARY KEY, kelurahan_id INTEGER, kode TEXT, nama TEXT, alamat TEXT, ketua TEXT, sekretaris TEXT, bendahara TEXT, masa_mulai TEXT, masa_selesai TEXT, kode_surat TEXT);
CREATE TABLE rt(id INTEGER PRIMARY KEY, rw_id INTEGER, kode TEXT, nama TEXT, alamat TEXT, ketua TEXT, bendahara TEXT, masa_mulai TEXT, masa_selesai TEXT);
CREATE TABLE users(id INTEGER PRIMARY KEY, nama TEXT, username TEXT UNIQUE, phone TEXT, email TEXT, password_hash TEXT, role TEXT, jabatan TEXT, rt_id INTEGER, rw_id INTEGER, household_id INTEGER, resident_id INTEGER, status TEXT DEFAULT 'aktif', last_login TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id INTEGER, expires_at INTEGER);
CREATE TABLE login_attempts(id INTEGER PRIMARY KEY, username TEXT, success INTEGER, at INTEGER);
CREATE TABLE households(id INTEGER PRIMARY KEY, no_kk TEXT UNIQUE, rt_id INTEGER, kepala_nama TEXT, alamat TEXT, status_domisili TEXT, telp TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE residents(id INTEGER PRIMARY KEY, household_id INTEGER, nik TEXT UNIQUE, nama TEXT, jk TEXT, tempat_lahir TEXT, tgl_lahir TEXT, agama TEXT, pekerjaan TEXT, status_kawin TEXT, hubungan TEXT, status TEXT DEFAULT 'hidup', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE letter_types(kode TEXT PRIMARY KEY, nama TEXT, butuh_kelurahan INTEGER DEFAULT 0, aktif INTEGER DEFAULT 1);
CREATE TABLE letter_requests(id INTEGER PRIMARY KEY, no_reg TEXT, user_id INTEGER, resident_id INTEGER, household_id INTEGER, rt_id INTEGER, jenis TEXT, keperluan TEXT, keterangan TEXT, lampiran TEXT, status TEXT, catatan TEXT, rt_verified_by INTEGER, rt_verified_at TEXT, rw_verified_by INTEGER, rw_verified_at TEXT, approved_by INTEGER, approved_at TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE letter_logs(id INTEGER PRIMARY KEY, request_id INTEGER, user_id INTEGER, aksi TEXT, catatan TEXT, at TEXT);
CREATE TABLE issued_letters(id INTEGER PRIMARY KEY, request_id INTEGER UNIQUE, nomor TEXT UNIQUE, tanggal TEXT, file_path TEXT, verif_code TEXT UNIQUE, sig_rt_id INTEGER, sig_rw_id INTEGER, signer_name TEXT, signer_jabatan TEXT, status TEXT DEFAULT 'final', created_at TEXT);
CREATE TABLE counters(key TEXT PRIMARY KEY, value INTEGER);
CREATE TABLE signature_assets(id INTEGER PRIMARY KEY, user_id INTEGER, nama_pejabat TEXT, jabatan TEXT, file_path TEXT, versi INTEGER, is_active INTEGER, uploaded_by INTEGER, uploaded_at TEXT, deactivated_at TEXT);
CREATE TABLE dues_types(id INTEGER PRIMARY KEY, nama TEXT, nominal INTEGER, periode TEXT, level TEXT, aktif INTEGER DEFAULT 1, keterangan TEXT);
CREATE TABLE dues_invoices(id INTEGER PRIMARY KEY, dues_type_id INTEGER, household_id INTEGER, periode TEXT, nominal INTEGER, status TEXT, created_at TEXT, UNIQUE(dues_type_id, household_id, periode));
CREATE TABLE payments(id INTEGER PRIMARY KEY, invoice_id INTEGER, amount INTEGER, method TEXT, tanggal TEXT, receipt_no TEXT UNIQUE, ref TEXT, received_by INTEGER, status TEXT, catatan TEXT, created_by INTEGER, created_at TEXT, cancelled_by INTEGER, cancel_reason TEXT, bukti_file TEXT);
CREATE TABLE condolence_rules(id INTEGER PRIMARY KEY, nama TEXT, nominal_default INTEGER, sifat TEXT, metode TEXT, berlaku_mulai TEXT, cakupan_rt_id INTEGER, aktif INTEGER DEFAULT 1, catatan TEXT);
CREATE TABLE condolence_events(id INTEGER PRIMARY KEY, kode TEXT UNIQUE, tanggal TEXT, almarhum TEXT, usia INTEGER, rt_id INTEGER, household_id INTEGER, keluarga_kontak TEXT, alamat TEXT, rule_id INTEGER, nominal_target INTEGER, sifat TEXT, status TEXT, catatan TEXT, review_status TEXT DEFAULT 'draft', reviewed_by INTEGER, reviewed_at TEXT, review_note TEXT, created_by INTEGER, created_at TEXT);
CREATE TABLE condolence_contributions(id INTEGER PRIMARY KEY, event_id INTEGER, household_id INTEGER, expected INTEGER, amount INTEGER DEFAULT 0, tanggal TEXT, method TEXT, receipt_no TEXT UNIQUE, received_by INTEGER, status TEXT, verified TEXT, ref TEXT, catatan TEXT, created_at TEXT);
CREATE TABLE condolence_disbursements(id INTEGER PRIMARY KEY, event_id INTEGER, jenis TEXT, amount INTEGER, tanggal TEXT, penerima TEXT, saksi TEXT, bukti TEXT, keterangan TEXT, created_by INTEGER, created_at TEXT);
CREATE TABLE cash_transactions(id INTEGER PRIMARY KEY, buku TEXT, rt_id INTEGER, tanggal TEXT, no_bukti TEXT, jenis TEXT, kategori TEXT, uraian TEXT, amount INTEGER, bukti_file TEXT, status TEXT, created_by INTEGER, checked_by INTEGER, checked_at TEXT, ref_type TEXT, ref_id INTEGER, created_at TEXT);
CREATE TABLE complaints(id INTEGER PRIMARY KEY, kode TEXT, user_id INTEGER, rt_id INTEGER, kategori TEXT, judul TEXT, isi TEXT, lokasi TEXT, lampiran TEXT, status TEXT, is_private INTEGER DEFAULT 1, created_at TEXT, updated_at TEXT);
CREATE TABLE complaint_responses(id INTEGER PRIMARY KEY, complaint_id INTEGER, user_id INTEGER, isi TEXT, status_baru TEXT, at TEXT);
CREATE TABLE announcements(id INTEGER PRIMARY KEY, judul TEXT, isi TEXT, jenis TEXT, target_rt_id INTEGER, tanggal_kegiatan TEXT, lokasi TEXT, tayang_mulai TEXT, tayang_selesai TEXT, created_by INTEGER, created_at TEXT);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, user_id INTEGER, username TEXT, aksi TEXT, entitas TEXT, entitas_id TEXT, detail TEXT, at TEXT);
